http:request.http:body:
#[output application/x-www-form-urlencoded --- {
                        grant_type: "authorization_code", client_id: p('idp.clientId'), code: vars.query.code,
                        redirect_uri: vars.baseUrl ++ "/callback", code_verifier: vars.session.verifier
                    } ++ (if (isEmpty(p('idp.clientSecret'))) {} else {client_secret: p('idp.clientSecret')})]

ee:variables.ee:set-variable:
%dw 2.0
import fromBase64 from dw::core::Binaries
import repeat from dw::core::Strings
output application/java
// Received directly from the identity provider over TLS: decoding for display is enough; the gateway
// validates the signature on every H360 call.
fun claims(jwt) = do {
    var part = (jwt splitBy ".")[1] replace "-" with "+" replace "_" with "/"
    var padded = part ++ repeat("=", if ((sizeOf(part) mod 4) == 0) 0 else 4 - (sizeOf(part) mod 4))
    ---
    read(fromBase64(padded), "application/json")
}
---
{
    access_token: payload.access_token,
    id_token: payload.id_token,
    claims: claims(payload.access_token) filterObject ((v, k) -> ["name", "preferred_username", "sf_username", "exp"] contains (k as String))
}

set-variable.value:
#[output application/java --- {name: 'dispatch_readonly', args: {
            url: '/services/data/' ++ p('h360.apiVersion') ++ '/query', method: 'GET',
            queryParams: {q: 'SELECT Id, Name, Account.Name, Amount, StageName, CloseDate, Owner.Name FROM Opportunity WHERE Amount != null ORDER BY Amount DESC LIMIT 3'}}}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    runningAs: vars.runningAs,
    rows: (vars.top.body.records default []) map {
        id: $.Id, name: $.Name, account: $.Account.Name, amount: $.Amount,
        stage: $.StageName, close: $.CloseDate, owner: $.Owner.Name
    }
}

set-variable.value:
#[output application/java --- {name: 'dispatch_readonly', args: {
            url: '/services/data/' ++ p('h360.apiVersion') ++ '/query', method: 'GET',
            queryParams: {q: 'SELECT Name, Amount, Owner.Name FROM Opportunity WHERE Id = \'' ++ (vars.oppId replace /[^a-zA-Z0-9]/ with '') ++ '\''}}}]

#[output application/java --- {name: 'dispatch', args: {
            url: '/services/data/' ++ p('h360.apiVersion') ++ '/sobjects/Opportunity/' ++ (vars.oppId replace /[^a-zA-Z0-9]/ with ''),
            method: 'PATCH', body: {Amount: vars.rec.Amount}}}]

#[output application/java --- do { var n = trim(payload.name default '') --- {
            name: if (isEmpty(n)) 'OBO Demo - Live' else if (sizeOf(n) > 120) n[0 to 119] else n,
            amount: ((payload.amount default '1000000') as String replace /[^0-9.]/ with '') as Number}}]

#[output application/java --- {name: 'dispatch_readonly', args: {
            url: '/services/data/' ++ p('h360.apiVersion') ++ '/query', method: 'GET',
            queryParams: {q: 'SELECT Name, Amount, Account.Name, Owner.Name, CreatedBy.Name FROM Opportunity WHERE Id = \'' ++ vars.created.body.id ++ '\''}}}]

ee:message.ee:set-payload:
%dw 2.0
output application/java
// Streamable HTTP answers with plain JSON or an SSE stream ("data: {...}" lines)
var text = payload as String
var data = (text splitBy "\n") filter ($ startsWith "data:")
var msg = if (isEmpty(data)) read(text, "application/json") else read(trim(data[-1][5 to -1]), "application/json")
---
if (msg.error != null) { mcpError: msg.error.message default "MCP error" }
else read(msg.result.content[0].text default "{}", "application/json")
